select set_config('lumiscore.catalog_release_receipt','{"rows":[{"key":{"id":987210001},"seq":1,"relation":"editions","after_row":{"id":987210001,"title":"Pijpelijntjes","isbn_10":null,"isbn_13":"9789065210937","work_id":987110001,"cover_id":null,"language":"dut","publisher":"Peter van der Velden","publish_date":null,"open_library_edition_id":"OL24298393M"},"before_row":{"id":987210001,"title":"Pijpelijntjes","isbn_10":null,"isbn_13":null,"work_id":987110001,"cover_id":null,"language":null,"publisher":"Peter van der Velden","publish_date":null,"open_library_edition_id":"OL24298393M"}},{"key":{"work_id":987110001,"language":"nl"},"seq":2,"relation":"catalog_work_descriptions","after_row":{"text":"In de Amsterdamse wijk De Pijp speelt zich de verhouding tussen twee jonge mannen af. Hun omgang met elkaar maakt deel uit van een levendige buurtwereld waarin ook buren, bezoekers en alledaagse ontmoetingen een plaats krijgen. De roman brengt homoseksueel verlangen openlijk ter sprake in een omgeving waarin dat sterke afkeuring oproept. Jacob Israël de Haan verbindt de intimiteit van de relatie met het straatleven en de sociale verhoudingen rond zijn hoofdpersonen.","work_id":987110001,"evidence":[{"note":"Same DeHaan novel Pijpelijntjes, no names dependent on1904version in summary. No assertion that historical textual revisions are identical. Exact current source-edition key is already present; fill its absent ISBN from bound independent KB records, never insert a duplicate edition. Only Pijpelijntjes additionally needs NULL-language→dut based on exact KB language evidence.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p82024015X"],"reference":"work:1201","checked_at":"2026-11-02T19:45:00.000Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-020.json","sources":["https://www.dbnl.org/tekst/haan008pijp01_01/haan008pijp01_01_0025.php","https://openlibrary.org/works/OL3698641